import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.TrimData{Patterns: []protocol.TrimPattern{{ItemName: "item_a", PatternID: "pat_a"}},
# Materials: []protocol.TrimMaterial{{MaterialID: "mat_a", Colour: "c", ItemName: "item_b"}}}
GOLDEN = bytes.fromhex("01066974656d5f61057061745f6101056d61745f610163066974656d5f62")

# generated by gophertunnel b8bd735:
# &packet.TrimData{}
EMPTY = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(
        v2225.TrimDataPacket(
            trim_patterns=[v2225.TrimPattern(item_name="item_a", pattern_id="pat_a")],
            trim_materials=[v2225.TrimMaterial(material_id="mat_a", color="c", item_name="item_b")],
        ),
        GOLDEN,
        id="one-pattern-one-material",
    ),
    pytest.param(v2225.TrimDataPacket(), EMPTY, id="empty"),
]


def test_trim_data_is_packet_302():
    assert v2225.PACKETS[302] is v2225.TrimDataPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_trim_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_trim_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", [v1001, v2168])
def test_1001_and_2168_resolve_trim_data_to_the_latest_type(version):
    assert version.PACKETS[302] is v2225.TrimDataPacket
